INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9201, '2 Kings 9:5', '2 Kings', 9, 5, '&nbsp;هلته يې د فوج آفسران وليدل چې راغونډ وُو. هغۀ وفرمائيل، ”صاحِبه، ما سره ستا دپاره يو پېغام دے.“ ياهُو ورته ووئيل، ”تۀ په مونږ کښې چا ته وائې؟“ نو هغۀ ورته وفرمائيل، ”د فوج مشره، تا ته وايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9202, '2 Kings 9:6', '2 Kings', 9, 6, '&nbsp;نو هغوئ دواړه دننه لاړل او هغه زلمى پېغمبر د ياهُو سر د زيتُونو په تېلو غوړ کړو او ورته يې وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دا اِعلان کوى چې زۀ تا په خپلو خلقو اِسرائيل باندې بادشاه مقرروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9203, '2 Kings 9:7', '2 Kings', 9, 7, '&nbsp;تۀ به د خپل نېک د اخى‌اب کورنۍ تباه کوې، نو داسې به زۀ ايزبل له سزا ورکړم ځکه چې هغې زما پېغمبران او زما نور خِدمت کوونکى وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9204, '2 Kings 9:8', '2 Kings', 9, 8, '&nbsp;د اخى‌اب مکمل خاندان او اولاد به مرى، زۀ به د هغۀ په خاندان کښې هر يو نارينه ختم کړم، کۀ هغه بوډا وى او کۀ ځوان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9205, '2 Kings 9:9', '2 Kings', 9, 9, '&nbsp;زۀ به د هغۀ د خاندان سره هم هغه شان سلوک وکړم لکه څنګه سلوک مې چې د اِسرائيل د بادشاهانو د نباط زوئ يربعام او د اخياه زوئ بعشا سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9206, '2 Kings 9:10', '2 Kings', 9, 10, '&nbsp;ايزبل به هيڅ څوک نۀ ښخوى، او د يزرعيل په علاقه کښې به سپى د هغې لاش وخورى.“ بيا هغه ځوان پېغمبر دروازه کولاو کړه او منډه يې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9207, '2 Kings 9:11', '2 Kings', 9, 11, '&nbsp;ياهُو خپلو ملګرو آفسرانو له واپس لاړو، چې هغوئ ترې نه تپوس وکړو، ”خېر خو دے؟ هغه ليونے تا له د څۀ دپاره راغلے وو؟“ ياهُو ورته ووئيل، ”تاسو ته پته ده چې هغه څنګه سړے دے او څنګه خبرې کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9208, '2 Kings 9:12', '2 Kings', 9, 12, '&nbsp;هغوئ ورته ووئيل، ”مونږ ته رښتيا خبره وکړه چې هغۀ څۀ وفرمائيل.“ نو هغۀ جواب ورکړو چې، ”هغۀ ما ته وفرمائيل چې، مالِک خُدائ اِعلان کوى چې تا زۀ د اِسرائيل بادشاه مقرروم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9209, '2 Kings 9:13', '2 Kings', 9, 13, '&nbsp;نو سمدستى د ياهُو ملګرو آفسرانو خپلې چُوغې د پوړۍ دپاسه خورې کړې چې ياهُو ورباندې ودريږى، بيګلې يې وغږولې او چغه يې کړه، ”ياهُو بادشاه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9210, '2 Kings 9:16', '2 Kings', 9, 16, '&nbsp;بيا هغه په خپله جنګى ګاډۍ کښې سور شو او يزرعيل ته روان شو. يورام تر اوسه پورې روغ شوے نۀ وو او د يهوداه بادشاه اخزياه د هغۀ تپوس له ورغلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9211, '2 Kings 9:17', '2 Kings', 9, 17, '&nbsp;په يزرعيل کښې د څوکيدارۍ په برج کښې يو محافظ وو چې هغۀ ياهُو او د هغۀ فوجيان وليدل چې راروان وُو. هغۀ چغه کړه، ”ما يو څو سړى وليدل چې راروان دى.“ يورام ورته ووئيل، ”په آس سور يو سړے ورولېږه چې دا معلوم کړى چې خېر خو دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9212, '2 Kings 9:18', '2 Kings', 9, 18, '&nbsp;پېغام وړونکے ياهُو له ورَغلو او ورته يې ووئيل، ”بادشاه معلومول غواړى چې خېر خو دے څنګه راغلے يئ؟“ ياهُو ورته ووئيل، ”تاسو په خېر څۀ کوئ؟ ما پسې راځه.“ محافظ دا خبر ورکړو چې پېغام وړونکے هغه قبيلې ته رسېدلے دے خو واپس رانۀ غلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9213, '2 Kings 9:19', '2 Kings', 9, 19, '&nbsp;نو بادشاه په آس سور دوېم سړے ورولېږلو. کله چې هغه هغوئ له ورَغلو نو ورته يې ووئيل، ”بادشاه داسې وائى، خېر خو دے څنګه راغلے يې؟“ ياهُو ورته ووئيل، ”تاسو په خېر څۀ کوئ؟ ما پسې راځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9214, '2 Kings 9:20', '2 Kings', 9, 20, '&nbsp;محافظ يو ځل بيا خبر ولېږلو چې پېغام وړونکے هغه قبيلې ته رسېدلے دے خو واپس رانۀ غلو. او هغۀ دا هم ووئيل، ”هغه خپله جنګى ګاډۍ د ليونى په شان چلوى، لکه چې ياهُو وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9215, '2 Kings 9:21', '2 Kings', 9, 21, '&nbsp;يورام بادشاه حُکم وکړو، ”زما جنګى ګاډۍ تياره کړئ.“ نو هغوئ تياره کړه او هغه او اخزياه بادشاه روان شول، دواړه د ياهُو سره مِلاوېدو دپاره په خپله خپله جنګى ګاډۍ کښې سوارۀ وُو او د نبوت په پټى کښې ورسره مِلاو شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9216, '2 Kings 9:22', '2 Kings', 9, 22, '&nbsp;يورام ترې نه تپوس وکړو، ”خېر خو دے څنګه راغلې؟“ ياهُو ورته ووئيل، ”خېر به څنګه وى، چې په مونږ کښې هغه کوډې او بُت پرستى موجوده وى چې ستا مور ايزبل شروع کړې دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9217, '2 Kings 9:23', '2 Kings', 9, 23, '&nbsp;يورام چغه کړه، ”اخزياه، دا سازش دے.“ نو هغۀ سمدستى خپله جنګى ګاډۍ راتاو کړه او هغه روان شو چې وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9218, '2 Kings 9:24', '2 Kings', 9, 24, '&nbsp;ياهُو خپله لينده راوويسته او پوره يې راښکله او د يورام د ولو مينځ يې په غشى وويشتو او د هغۀ زړۀ يې سورے کړو. يورام په خپله جنګى ګاډۍ کښې مړ پرېوتو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9219, '2 Kings 9:25', '2 Kings', 9, 25, '&nbsp;او ياهُو خپل آفسر بِدقر ته ووئيل، ”د هغۀ لاش اوچت کړه او په هغه پټى کښې يې وغورزوه چې د نبوت دے. هغه راپه ياد کړه چې کله تۀ او زۀ د يورام بادشاه پلار اخى‌اب پسې روان وُو، نو مالِک خُدائ د اخى‌اب خِلاف دا کلام وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9220, '2 Kings 9:26', '2 Kings', 9, 26, '&nbsp;ما د نبوت او د هغۀ د زامنو قتل پرون وليدو. زۀ دا قسم کوم چې زۀ به تا له هم په دې پټى کښې سزا درکړم.“ نو ياهُو خپل آفسر له حُکم ورکړو چې، ”د يورام لاش اوچت کړه او په هغه پټى کښې يې واچوه چې کوم د نبوت دے، نو چې د مالِک خُدائ قسم پوره شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9221, '2 Kings 9:27', '2 Kings', 9, 27, '&nbsp;اخزياه خبر شو چې څۀ شوى وُو، نو هغه په خپله جنګى ګاډۍ کښې د بيت‌هګان ښار طرف ته وتښتېدو او ياهُو ورپسې وو. ياهُو خپلو سړو له حُکم ورکړو، ”دے هم ووژنئ.“ او چې کله هغۀ د ابليعام ښار سره نزدې جور ته خپله جنګى ګاډۍ روانه کړې وه نو هغه يې زخمى کړو، خو تر هغې پورې روان وو چې د مِجدو ښار ته ورسېدو او هلته مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9222, '2 Kings 9:28', '2 Kings', 9, 28, '&nbsp;د هغۀ خپلو آفسرانو د هغۀ لاش په جنګى ګاډۍ کښې واپس يروشلم ته يوړو او د داؤد په ښار کښې په شاهى اديره کښې يې ښخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9223, '2 Kings 9:29', '2 Kings', 9, 29, '&nbsp;اخزياه د اخى‌اب د زوئ يورام د بادشاهۍ په يوولسم کال د يهوداه بادشاه جوړ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9224, '2 Kings 9:30', '2 Kings', 9, 30, '&nbsp;ياهُو يزرعيل ته ورسېدو. نو چې ايزبل خبر شوه، نو رانجۀ يې پورې کړل، وېښتۀ يې سم کړل او په محل کښې د يوې کړکۍ سره ودرېده او بهر يې کتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9225, '2 Kings 9:31', '2 Kings', 9, 31, '&nbsp;څنګه چې ياهُو دروازې ته راورسېدو، نو هغې ورته آواز وکړو، ”تۀ د زِمرى په شان يې، تۀ د خپل نېک قاتِل يې، تۀ څنګه دلته په خېر سره راغلې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9226, '2 Kings 9:32', '2 Kings', 9, 32, '&nbsp;ياهُو بره وکتل او چغه يې کړه، ”زما ملګرتيا څوک کوى؟“ دوو يا درېو خصيانو هغۀ ته لاندې وکتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9227, '2 Kings 9:33', '2 Kings', 9, 33, '&nbsp;او ياهُو هغوئ ته ووئيل، ”هغه لاندې راوغورزوئ.“ نو هغوئ هغه لاندې راوغورزوله او آسونو د هغې لاش د پښو لاندې کړو او د هغې په وينو باندې دېوال او آسونه لت پت شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9228, '2 Kings 9:34', '2 Kings', 9, 34, '&nbsp;بيا ياهُو لاړو او د خوراک څښاک نه پس هغۀ ووئيل، ”دا لعنتى ښځه بوځئ او ښخه يې کړئ، کۀ څۀ هم وى خو د بادشاه لور خو ده کنه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9229, '2 Kings 9:35', '2 Kings', 9, 35, '&nbsp;خو چې سړى د هغې ښخېدلو له ورغلل نو هغوئ د هغې کوپړۍ، پښو او د هغې د لاسونو نه بغېر هيڅ هم ونۀ موندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9230, '2 Kings 9:36', '2 Kings', 9, 36, '&nbsp;کله چې هغوئ ياهُو د دې نه خبر کړو، نو هغۀ ووئيل، ”دا هغه څۀ دى چې مالِک خُدائ فرمائيلى وُو چې داسې به کيږى، کله چې هغۀ د خپل خِدمت کوونکى الياس په ذريعه دا کلام کړے وو يعنې، د يزرعيل په علاقه کښې به سپى د ايزبل لاش وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9231, '2 Kings 9:37', '2 Kings', 9, 37, '&nbsp;د ايزبل لاش د يزرعيل په مُلک کښې په يو پټى کښې به په زمکه باندې د سوټو په شان خور ورو پروت وى او څوک به هم نۀ وى چې هغه وپېژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9232, '2 Kings 10:1', '2 Kings', 10, 1, '&nbsp;د اخى‌اب بادشاه اويا زامن د سامريه په ښار کښې اوسېدل. ياهُو يو خط وليکلو او د ښار حکمرانانو، د ښار مشرانو او د اخى‌اب د اولاد مشرانو له يې د دې نقلونه ولېږل. په خط کښې دا وئيلى شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9233, '2 Kings 10:2', '2 Kings', 10, 2, '&nbsp;”تاسو د بادشاه د زامنو مشران يئ او ستاسو حِفاظت د جنګى ګاډو، آسونو، وسلو او د پَخو دېوالونو د ښارونو سره کيږى. چې څنګه تاسو ته دا خط مِلاو شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9234, '2 Kings 10:3', '2 Kings', 10, 3, '&nbsp;نو تاسو د بادشاه د زامنو نه يو ښۀ کس خوښ کړئ، هغه بادشاه جوړ کړئ او د هغۀ د حِفاظت دپاره جنګ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9235, '2 Kings 10:4', '2 Kings', 10, 4, '&nbsp;د سامريه حکمرانان ويرېدل. هغوئ ووئيل، ”يورام بادشاه او اخزياه بادشاه چې د ياهُو مخالفت نۀ شو کولے نو مونږ د هغۀ مخالفت څنګه وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9236, '2 Kings 10:5', '2 Kings', 10, 5, '&nbsp;نو د محل آفسر او د ښار آفسر، سره د ښار د مشرانو او د بادشاه د زامنو محافظانو، ياهُو له دا پېغام ولېږلو، ”مونږ ستا خِدمت کوونکى يُو او چې تۀ څۀ وائې نو هغې ته تيار يُو. خو مونږ د هيچا نه هم بادشاه نۀ جوړوُو، چې څۀ تا ته ښۀ ښکارى نو هم هغه وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9237, '2 Kings 10:6', '2 Kings', 10, 6, '&nbsp;ياهُو هغوئ ته يو بل خط وليکلو، ”کۀ تاسو زما ملګرتيا کوئ او زما حُکمونو منلو ته تيار يئ، نو سبا دا وخت په يزرعيل کښې د اخى‌اب بادشاه د زامنو سرونه ما له راوړئ.“ د اخى‌اب بادشاه اويا زامن د سامريه ښار د مشرانو د حِفاظت لاندې لوئ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9238, '2 Kings 10:7', '2 Kings', 10, 7, '&nbsp;چې کله د ياهُو خط راورسېدو، نو د سامريه مشرانو د اخى‌اب هغه اويا واړه زامن ووژل، د هغوئ سرونه يې په ټوکرو کښې واچول او په يزرعيل کښې يې ياهُو له ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9239, '2 Kings 10:8', '2 Kings', 10, 8, '&nbsp;کله چې ياهُو خبر شو چې د اخى‌اب د زامنو سرونه راوړے شوى دى، نو هغۀ حُکم ورکړو چې د دې نه د ښار د دروازې په خولۀ کښې دوه ډيرى جوړ کړئ او تر سحر پورې دې هلته پرېښودلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9240, '2 Kings 10:9', '2 Kings', 10, 9, '&nbsp;په سحر کښې، هغه د ښار دروازې له لاړو او چې کوم خلق هلته وُو نو هغوئ ته يې ووئيل، ”زۀ هغه څوک يم چا چې د يورام بادشاه خِلاف منصوبه جوړه کړه او هغه يې ووژلو، تاسو د هغې ذمه وار نۀ يئ. خو دا ټول چا ووژل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9241, '2 Kings 10:10', '2 Kings', 10, 10, '&nbsp;تاسو يقين وکړئ چې د مالِک خُدائ کوم پېغام د اخى‌اب د خاندان په حقله بيان شوے وو هغه به نۀ ناکام کيږى. مالِک خُدائ د خپل خِدمت کوونکى الياس په ذريعه دا اِعلان کړے وو چې داسې به کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9242, '2 Kings 10:11', '2 Kings', 10, 11, '&nbsp;بيا ياهُو د اخى‌اب نور ټول خپلوان ووژل چې کوم په يزرعيل کښې اوسېدل او د هغۀ ټول آفسران، نزدې ملګرى او اِمامان هم، د هغوئ نه يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9243, '2 Kings 10:12', '2 Kings', 10, 12, '&nbsp;ياهُو سامريه ته روان شو. په لار کښې، د هغه ځائ سره چې نوم يې ”د شپانو ځائ“ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9244, '2 Kings 10:13', '2 Kings', 10, 13, '&nbsp;هغه د يهوداه د مړ بادشاه اخزياه د يو څو خپلوانو سره مِلاو شو او د هغوئ نه يې تپوس وکړو، ”تاسو څوک يئ؟“ هغوئ ورته ووئيل، ”مونږ د اخزياه خپلوان يُو، مونږ يزرعيل ته روان يُو چې د مَلِکه ايزبل او د شاهى خاندان د نورو کسانو درناوے وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9245, '2 Kings 10:14', '2 Kings', 10, 14, '&nbsp;ياهُو خپلو سړو له حُکم ورکړو، ”هغوئ ژوندى ونيسئ.“ نو هغوئ يې ونيول او هغوئ يې هلته د يوې کندې سره نزدې ووژل. هغوئ ټول دوه څلوېښت کسان وُو او د هغوئ نه يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9246, '2 Kings 10:15', '2 Kings', 10, 15, '&nbsp;ياهُو يو ځل بيا روان شو، په لار کښې هغه د ريکاب زوئ يوندب سره مِلاو شو. ياهُو ورباندې سلام واچولو او ورته يې ووئيل، ”تۀ هم زما هغه شان وفادار يې لکه چې څنګه زۀ ستا وفادار يم؟“ يوندب ورته ووئيل، ”آو، زۀ ستا وفادار يم.“ ياهُو ورته ووئيل، ”کۀ داسې وى نو ما له لاس راکړه.“ نو هغۀ لاس ورکړو. ياهُو هغه د ځان سره خپلې جنګى ګاډۍ ته وخېژولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9247, '2 Kings 10:16', '2 Kings', 10, 16, '&nbsp;او هغۀ ورته ووئيل، ”ما سره لاړ شه او په خپله وګوره چې زۀ د مالِک خُدائ څومره وفادار يم.“ او هغه يې په خپله جنګى ګاډۍ کښې بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9248, '2 Kings 10:17', '2 Kings', 10, 17, '&nbsp;کله چې هغوئ سامريه ته راغلل، نو ياهُو د اخى‌اب ټول پاتې شوى خپلوان ووژل، تر دې پورې چې يو هم ژوندے پاتې نۀ شو، هم هغه شان چې څنګه مالِک خُدائ الياس ته کلام کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9249, '2 Kings 10:18', '2 Kings', 10, 18, '&nbsp;ياهُو د سامريه ټول خلق راغونډ کړل او ورته يې ووئيل، ”اخى‌اب بادشاه د بعل بُت لږ شان خِدمت کړے دے، خو زۀ به يې د هغۀ نه هم زيات خِدمت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9250, '2 Kings 10:19', '2 Kings', 10, 19, '&nbsp;د بعل ټول پېغمبران، د هغۀ ټول عبادت کوونکى او ټول اِمامان راغونډ کړئ. هيڅ څوک به غېر حاضر نۀ وى، زۀ بعل ته يوه لويه قربانى پېش کوم او چې څوک هم حاضر نۀ شى نو هغه به وژلے شى.“ خو د ياهُو مطلب دا وو چې داسې به د بعل عبادت کوونکى ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9251, '2 Kings 10:20', '2 Kings', 10, 20, '&nbsp;بيا ياهُو اِعلان وکړو، ”د بعل د درناوى دپاره د عبادت د ورځې اِعلان وکړئ.“ نو اِعلان وشو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9252, '2 Kings 10:21', '2 Kings', 10, 21, '&nbsp;او ياهُو د اِسرائيل ټول مُلک ته دا خبر ولېږلو، او د بعل عبادت کوونکى ټول راغلل نو يو کس هم پاتې نۀ شو چې غېر حاضر وى. هغوئ ټول د بعل عبادتخانې ته راغلل او د يو سر نه تر بل سره پورې يې عبادتخانه ډکه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9253, '2 Kings 10:22', '2 Kings', 10, 22, '&nbsp;بيا ياهُو د مقدسو چُوغو مشر اِمام له حُکم ورکړو چې چُوغې راوړه او عبادت کوونکو له يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9254, '2 Kings 10:23', '2 Kings', 10, 23, '&nbsp;د هغې نه پس، ياهُو په خپله د ريکاب زوئ يوندب سره عبادتخانې ته دننه شو او خلقو ته يې هلته ووئيل، ”پام کوئ چې صِرف د بعل عبادت کوونکى حاضر وى او د مالِک خُدائ يو عبادت کوونکے هم نۀ وى راننوتلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9255, '2 Kings 10:24', '2 Kings', 10, 24, '&nbsp;بيا هغه او يوندب دننه لاړل چې بعل ته قربانۍ او سوزېدونکې نذرانې پېش کړى. هغۀ اتيا سړى د عبادتخانې نه بهر ودرولى وُو او هغوئ ته يې وئيلى وُو، ”تاسو به دا ټول خلق وژنئ، چې د چا نه يو کس هم وتښتى نو د هغۀ په سر کښې به هغه وژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9256, '2 Kings 10:25', '2 Kings', 10, 25, '&nbsp;چې څنګه ياهُو نذرانې پېش کړې، نو هغۀ څوکيدارانو او آفسرانو ته ووئيل، ”دننه ورشئ او ټول ووژنئ، چې يو هم درنه خلاص نۀ شى.“ هغوئ تُورې راويستلې او دننه لاړل، ټول يې ووژل او د هغوئ لاشونه يې بهر راښکل. بيا هغوئ د عبادتخانې دنننى ځائ ته لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9257, '2 Kings 10:26', '2 Kings', 10, 26, '&nbsp;چې هلته کومه مقدسه ستنه وه هغه يې راوويستله او وې سوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9258, '2 Kings 10:27', '2 Kings', 10, 27, '&nbsp;نو هغوئ د عبادت ستنه او عبادتخانه تباه کړه او عبادتخانه په ټټۍ بدله شوه او تر نن ورځې پورې شته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9259, '2 Kings 10:28', '2 Kings', 10, 28, '&nbsp;نو ياهُو داسې د اِسرائيل نه د بعل عبادت ختم کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9260, '2 Kings 10:29', '2 Kings', 10, 29, '&nbsp;خو هغۀ د يربعام بادشاه ګناه بنده نۀ کړه، چا چې اِسرائيليان د ګناه طرف ته بوتلى وُو چې هغوئ د سرو زرو د هغه سخى عبادت وکړو چې هغۀ په بيت‌ايل او دان کښې لګولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9261, '2 Kings 10:30', '2 Kings', 10, 30, '&nbsp;مالِک خُدائ ياهُو ته وفرمائيل، ”تا د اخى‌اب په اولاد باندې هم هغه څۀ وکړل چې ما درته فرمائيلى وُو. نو زۀ تا سره لوظ کوم چې ستا اولاد به تر څلورم نسل پورې د اِسرائيل بادشاهان وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9262, '2 Kings 10:31', '2 Kings', 10, 31, '&nbsp;خو ياهُو د زړۀ د اخلاصه د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک قانون نۀ منلو. هغه د يربعام د هغه ګناهونو نه نۀ راګرځېدو، چې په بنى اِسرائيلو باندې يې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9263, '2 Kings 10:32', '2 Kings', 10, 32, '&nbsp;په هغه وخت کښې مالِک خُدائ د اِسرائيل د علاقې کمول شروع کړل. د شام بادشاه حِزائيل د اِسرائيل ټوله علاقه فتح کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9264, '2 Kings 10:33', '2 Kings', 10, 33, '&nbsp;د اُردن نمرخاتۀ طرف ته، د ارنون سيند په غاړه په جنوب کښې د عروعير ښار پورې، په دې کښې د جِلعاد او بسن علاقې هم شاملې وې، چرته چې د جاد، روبين او نمرخاتۀ طرف ته منسى قبيلې اوسېدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9265, '2 Kings 10:34', '2 Kings', 10, 34, '&nbsp;نور هر څۀ چې ياهُو کړى وُو، سره د هغۀ د بهادرۍ د کارنامو، دا د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9266, '2 Kings 10:35', '2 Kings', 10, 35, '&nbsp;هغه مړ شو او په سامريه کښې ښخ شو او د هغۀ زوئ يهوآخز د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9267, '2 Kings 10:36', '2 Kings', 10, 36, '&nbsp;ياهُو په سامريه کښې اتۀويشت کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9268, '2 Kings 11:1', '2 Kings', 11, 1, '&nbsp;څنګه چې د اخزياه مور عتلياه د خپل زوئ د قتل نه خبر شوه، نو هغې ووئيل چې د شاهى خاندان ټول کسان دې ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9269, '2 Kings 11:2', '2 Kings', 11, 2, '&nbsp;صِرف د اخزياه زوئ يوآس وتښتېدو. هغه هم د نورو سره وژلے کېدو، خو يهوسبع هغه بچ کړو، يهوسبع د يهورام لور او د اخزياه ناسکه خور وه. هغې يوآس او د هغۀ دايڼه د مالِک خُدائ په کور کښې د خوب کوټې ته بوتلل او د عتلياه نه يې پټ کړو، نو هغه ونۀ وژلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9270, '2 Kings 11:3', '2 Kings', 11, 3, '&nbsp;شپږ کاله يهوسبع د هلک خيال ساتلو او د مالِک خُدائ په کور کښې يې پټ کړے وو، چې په دې دوران کښې عتلياه مَلِکه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9271, '2 Kings 11:4', '2 Kings', 11, 4, '&nbsp;خو په اوؤم کال يهويدع اِمام د شاهى څوکيدارانو او د محل څوکيدارانو مشران آفسران راوغوښتل او د مالِک خُدائ کور ته يې راوستل، چې هلته يې د هغوئ نه دا قسم واخستلو چې د هغۀ په منصوبه به عمل کوى. نو بيا هغۀ ورته د اخزياه بادشاه زوئ يوآس وښودلو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9272, '2 Kings 11:5', '2 Kings', 11, 5, '&nbsp;او هغوئ له يې دا حُکم ورکړو، ”کله چې تاسو د سبت په ورځ خپل کار له راشئ، نو ستاسو درېمه حِصه کسان به د محل څوکيدارى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9273, '2 Kings 11:6', '2 Kings', 11, 6, '&nbsp;بله درېمه حِصه به د صور په دروازه کښې د څوکيدارۍ دپاره ودريږى او بله درېمه حِصه به د نورو څوکيدارانو وروستو د دروازې سره د څوکيدارۍ دپاره ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9274, '2 Kings 11:7', '2 Kings', 11, 7, '&nbsp;هغه دواړه ډلې چې د سبت په ورځ يې چُټى وى نو هغه به د مالِک خُدائ په کور د بادشاه د څوکيدارۍ دپاره ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9275, '2 Kings 11:8', '2 Kings', 11, 8, '&nbsp;تاسو به د يوآس بادشاه نه ګېرچاپېره ولاړ يئ او تُورې به مو راويستلې وى او چې چرته هم ځى نو ورسره ځئ. هر څوک چې تاسو له نزدې راځى نو هغه دې وژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9276, '2 Kings 11:9', '2 Kings', 11, 9, '&nbsp;آفسرانو د يهويدع په خبرو عمل وکړو او هغوئ هغه سړى ورله راوستل چې د سبت په ورځ په چُټۍ تلل او چې کوم څوکيدارۍ له راتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9277, '2 Kings 11:10', '2 Kings', 11, 10, '&nbsp;هغۀ آفسرانو له هغه نېزې او ډالونه ورکړل کوم چې د داؤد بادشاه وُو او چې د مالِک خُدائ په کور کښې ساتلے شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9278, '2 Kings 11:11', '2 Kings', 11, 11, '&nbsp;او هغۀ د مالِک خُدائ د کور په مخکښې ګېرچاپېره د بادشاه د حِفاظت دپاره سړى ودرول چې تُورې يې په لاس کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9279, '2 Kings 11:12', '2 Kings', 11, 12, '&nbsp;بيا يهويدع يوآس بهر بوتلو، تاج يې ورپه سر کړو او د بادشاهۍ کولو د قانون يو نقل يې ورله ورکړو. نو يوآس مقرر کړے شو او اِعلان وشو چې هغه بادشاه دے. خلقو لاسونه وپړقول او چغه يې ووهله، ”بادشاه زنده‌باد.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9280, '2 Kings 11:13', '2 Kings', 11, 13, '&nbsp;مَلِکه عتلياه د څوکيدارانو او خلقو شور واورېدو، نو هغه د مالِک خُدائ کور ته تېزه لاړه، چرته چې خلق راغونډ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9281, '2 Kings 11:14', '2 Kings', 11, 14, '&nbsp;هلته هغې هغه نوے بادشاه وليدو چې د رِواج په مطابق د ستنې سره د مالِک خُدائ د کور د دروازې په خولۀ کښې ولاړ وو. آفسران او بيګل غږوونکى د هغۀ نه ګېرچاپېره تاو وُو او ټولو خلقو د خوشحالۍ نه چغې وهلې او بيګلې يې غږولې. عتلياه د خفګان نه خپلې جامې وشلولې او چغې يې ووهلې، ”غدار، غدار.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9282, '2 Kings 11:15', '2 Kings', 11, 15, '&nbsp;يهويدع نۀ غوښتل چې عتلياه د مالِک خُدائ د کور سره ووژنى، نو هغۀ فوجى آفسرانو له حُکم ورکړو، ”هغه د څوکيدارانو د صفونو په مينځ کښې وباسئ او هغه هر يو کس ووژنئ چې د هغې د بچ کولو کوشش وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9283, '2 Kings 11:16', '2 Kings', 11, 16, '&nbsp;هغوئ هغه ونيوله، محل ته يې بوتله او هلته يې د آسونو د دروازې سره ووژله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9284, '2 Kings 11:17', '2 Kings', 11, 17, '&nbsp;يهويدع اِمام د يوآس بادشاه او د خلقو نه د مالِک خُدائ په نوم يو لوظ واخستلو چې هغوئ به د مالِک خُدائ تابعدار اوسى، هغۀ د بادشاه او د خلقو په مينځ کښې هم يو لوظ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9285, '2 Kings 11:18', '2 Kings', 11, 18, '&nbsp;بيا خلق د بعل عبادتخانې ته لاړل او راوې غورزوله، هغوئ قربان‌ګاه او بُتان ټوټې ټوټې کړل او د بعل اِمام متان يې د قربان‌ګاه په مخکښې ووژلو. يهويدع د مالِک خُدائ په کور باندې څوکيداران ودرول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9286, '2 Kings 11:19', '2 Kings', 11, 19, '&nbsp;او بيا هغۀ، آفسرانو، شاهى څوکيدارانو او د محل څوکيدارانو بادشاه د مالِک خُدائ د کور نه محل ته بوتلو، چې ټول خلق ورپسې روان وُو. يوآس د څوکيدارانو په دروازه ننوتلو او په تخت باندې په خپل ځائ کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9287, '2 Kings 11:20', '2 Kings', 11, 20, '&nbsp;ټول خلق خوشحاله وُو او په ښار کښې امن وو، ځکه چې عتلياه په محل کښې وژلے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9288, '2 Kings 11:21', '2 Kings', 11, 21, '&nbsp;يوآس د اوو کالو په عُمر کښې د يهوداه بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9289, '2 Kings 12:1', '2 Kings', 12, 1, '&nbsp;د اِسرائيل د بادشاه ياهُو د بادشاهۍ په اوؤم کال، يوآس د يهوداه بادشاه شو او هغۀ څلوېښت کاله په يروشلم کښې بادشاهى وکړه. د هغۀ مور ضِبياه د بيرسبع وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9290, '2 Kings 12:2', '2 Kings', 12, 2, '&nbsp;هغۀ ټول عُمر هغه کار کولو چې مالِک خُدائ پرې رضا کېدو، ځکه چې يهويدع اِمام هغۀ له دا مشوره ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9291, '2 Kings 12:3', '2 Kings', 12, 3, '&nbsp;خو علاقائى عبادتخانې نۀ وې تباه شوى او خلقو بيا بيا هلته قربانۍ پېش کولې او خوشبوئى سوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9292, '2 Kings 12:4', '2 Kings', 12, 4, '&nbsp;يوآس اِمامان راوغوښتل او دا حُکم يې ورکړو چې هغه پېسې بچت کوئ چې د مالِک خُدائ په کور کښې د مقدسو نذرانو، د هرې ورځې قربانۍ او د رضاکارانه نذرانو دپاره ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9293, '2 Kings 12:5', '2 Kings', 12, 5, '&nbsp;هر يو اِمام به پېسې اخلى او د ضرورت په مطابق به يې د مالِک خُدائ د کور په مرمت کښې استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9294, '2 Kings 12:6', '2 Kings', 12, 6, '&nbsp;خو د يوآس د بادشاهۍ په درويشتم کال پورې هم اِمامانو د مالِک خُدائ په کور کښې څۀ مرمت نۀ وو کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9295, '2 Kings 12:7', '2 Kings', 12, 7, '&nbsp;نو هغۀ يهويدع او نور اِمامان راوغوښتل او د هغوئ نه يې تپوس وکړو، ”تاسو د مالِک خُدائ کور ولې نۀ دے مرمت کړے؟ تاسو به نورې پېسې نۀ اخلئ. د نن نه پس به دا صرف د مالِک خُدائ د کور په مرمت کښې استعمالولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9296, '2 Kings 12:8', '2 Kings', 12, 8, '&nbsp;اِمامان دې ته راضى شول چې هغوئ به د خلقو نه نورې پېسې نۀ راغونډوى خو د مالِک خُدائ کور مرمت کولو ته يې هم غاړه ونۀ نيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9297, '2 Kings 12:9', '2 Kings', 12, 9, '&nbsp;بيا يهويدع يو صندوق واخستلو، د دې په سر کښې يې سورے وکړو او صندوق يې د قربان‌ګاه ښى طرف ته کېښودو، چې د مالِک خُدائ کور ته د ننوتو ځائ سره وو. خلقو چې کومه چنده ورکوله نو د ننوتو په ځائ کښې مقرر شوى اِمام به هغه ټوله په صندوق کښې اچوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9298, '2 Kings 12:10', '2 Kings', 12, 10, '&nbsp;چې کله به هم په صندوق کښې ډېرې پېسې جمع شوې، نو شاهى منشى او مشر اِمام به راتلل، هغه پېسې به يې وشمېرلې چې د مالِک خُدائ کور ته به راوړلے شوې وې او په کڅوړو کښې به يې واچولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9299, '2 Kings 12:11', '2 Kings', 12, 11, '&nbsp;بيا به هغوئ دا پېسې هغه سړو له ورکولې چې د مالِک خُدائ په کور کښې د کار ذمه وار وُو او هغوئ به ترې نه ترکاڼانو، مِعمارانو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9300, '2 Kings 12:12', '2 Kings', 12, 12, '&nbsp;ګِلکارانو او د کاڼو جوړوونکو له ورکولې، هغه لرګى او کاڼى به يې پرې اخستل چې په مرمت کښې استعمالېدل او نور ټول ضرورى څيزونه به يې پرې اخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');